        "baton": "102",
        "year": 1583,
        "season": 1,
        "title": "图伦城起兵战",
        "kind": "battle",
        "place": {
            "name": "辽东建州苏克苏浒河畔图伦城",
            "lat": 41.785,
            "lng": 124.682
        },
        "leadGeneralId": "manzhou_nuerhachi",
